// --- quick joint picker ---
const GROUPS=[['Thân',j=>/^(hips|spine|chest|neck|head)$/.test(j)],['Tay trái',j=>/^L_(clavicle|shoulder|elbow|forearm|wrist)$/.test(j)],['Tay phải',j=>/^R_(clavicle|shoulder|elbow|forearm|wrist)$/.test(j)],['Chân trái',j=>/^L_(hip|knee|ankle)$/.test(j)],['Chân phải',j=>/^R_(hip|knee|ankle)$/.test(j)],['Ngón tay trái',j=>/^L_finger/.test(j)],['Ngón tay phải',j=>/^R_finger/.test(j)],['Ngón chân',j=>/_toe/.test(j)]];
const PARENT=Object.fromEntries(RIG.map(([n,p])=>[n,p])),CHILD={};for(let [n,p] of RIG)if(p&&!CHILD[p])CHILD[p]=n;
function syncPicker(){let el=$('jointPick'),s=selected;el.replaceChildren();if(!s?.actor&&s?.kind!=='object'){let o=document.createElement('option');o.textContent='— chọn nhân vật trên màn hình hoặc Tab —';o.value='';el.append(o);el.value='';return}
 if(s.kind==='object'){let o=document.createElement('option');o.textContent=s.label;el.append(o);return}
 let a=actors.find(a=>a.spec.id===s.actor),o=document.createElement('option');o.value='$root';o.textContent=s.actor+' · toàn thân (di chuyển / quay)';el.append(o);
 for(let [g,f] of GROUPS){let og=document.createElement('optgroup');og.label=g;for(let j of Object.keys(a.joints).filter(f)){let op=document.createElement('option');op.value=j;op.textContent=j;og.append(op)}el.append(og)}el.value=s.kind==='joint'?s.name:'$root'}
function pickJoint(actorId,name){let a=actors.find(a=>a.spec.id===actorId);if(!a)return;if(name==='$root'||!name)select({kind:'actor',actor:a.spec.id,g:a.root,label:a.spec.id});else select({kind:'joint',actor:a.spec.id,name,g:a.joints[name],label:a.spec.id+' / '+name});if($('tool').value==='camera')setTool('rotate');invalidate()}
$('jointPick').onchange=()=>{if(selected?.actor)pickJoint(selected.actor,$('jointPick').value);$('jointPick').blur()};
{let _sel=select;select=function(s){_sel(s);syncPicker();renderInspector()}}
// --- inspector: exact numbers for the selection (wheel = small step, Shift+wheel = big step) ---
function inspectorRows(){let s=selected;if(!s)return [];let g=s.g;const deg=(obj,ax)=>({get:()=>obj[ax]/rad,set:v=>{obj[ax]=v*rad},step:1,unit:'°'}),m=(obj,ax)=>({get:()=>obj[ax],set:v=>{obj[ax]=v},step:.01,unit:'m'});
 if(s.kind==='joint')return [['Xoay',['x','y','z'].map(ax=>({ax,...deg(g.rotation,ax)}))]];
 if(s.kind==='actor')return [['Vị trí',['x','y','z'].map(ax=>({ax,...m(g.position,ax)}))],['Hướng',[{ax:'yaw',...deg(g.rotation,'y')}]]];
 return [['Vị trí',['x','y','z'].map(ax=>({ax,...m(g.position,ax)}))],['Xoay',['x','y','z'].map(ax=>({ax,...deg(g.rotation,ax)}))],['Kích thước',['x','y','z'].map(ax=>({ax,...m(g.scale,ax),set:v=>{g.scale[ax]=Math.max(.01,v)}}))]]}
let inspInputs=[];
function renderInspector(){let el=$('inspector');el.replaceChildren();inspInputs=[];for(let [title,fields] of inspectorRows()){let lab=document.createElement('div');lab.className='inspTitle';lab.textContent=title;el.append(lab);for(let f of fields){let w=document.createElement('label');w.className='insp';w.textContent=f.ax.toUpperCase();let i=document.createElement('input');i.type='number';i.step=f.step;i.title=f.unit==='°'?'độ · cuộn chuột: ±1° (Shift ±10°)':'mét · cuộn chuột: ±1cm (Shift ±10cm)';
  const apply=v=>{if(!Number.isFinite(v)||!selected)return;playing=false;f.set(v);rememberNode(selected.g);invalidate();draw()};
  i.onchange=()=>{apply(parseFloat(i.value));autoCommit()};i.onkeydown=e=>{if(e.key==='Enter')i.blur()};
  i.addEventListener('wheel',e=>{e.preventDefault();let v=f.get()+(e.deltaY<0?1:-1)*f.step*(e.shiftKey?10:1);apply(+v.toFixed(4));i.value=+v.toFixed(f.unit==='°'?1:3);clearTimeout(i._t);i._t=setTimeout(autoCommit,400)},{passive:false});
  w.append(i);el.append(w);inspInputs.push([i,f])}}updateInspector()}
function updateInspector(){for(let [i,f] of inspInputs)if(document.activeElement!==i)i.value=+f.get().toFixed(f.unit==='°'?1:3)}
{let _draw=draw;draw=function(){_draw();updateInspector()}}
// --- keyboard: [ parent, ] child, Tab next character, R reset joint ---
window.addEventListener('keydown',e=>{if(!project||recording||editingText(e)||e.ctrlKey||e.metaKey||e.altKey||$('helpDlg').open)return;let c=e.code;
 if(c==='Tab'){e.preventDefault();if(!actors.length)return;let i=actors.findIndex(a=>a.spec.id===selected?.actor),n=actors[(i+(e.shiftKey?-1:1)+actors.length)%actors.length];pickJoint(n.spec.id,selected?.kind==='joint'?selected.name:'$root');return}
 if((c==='BracketLeft'||c==='BracketRight')&&selected?.actor){e.preventDefault();let cur=selected.kind==='joint'?selected.name:null,next=c==='BracketLeft'?(cur?PARENT[cur]:null):(cur?CHILD[cur]:'hips');pickJoint(selected.actor,next||'$root');return}
 if(c==='KeyR'&&selected){e.preventDefault();if(e.repeat)return;playing=false;let g=selected.g;if(selected.kind==='joint')g.rotation.set(0,0,0);else if(selected.kind==='object')g.rotation.set(0,0,0);else return;rememberNode(g);draw();$('status').textContent=selected.label+' về 0°';autoCommit()}},true);
// --- loop playback inside the selected key range ---
{let _toggle=togglePlay;togglePlay=function(){let ts=selTimes();if(!playing&&$('loopSel').checked&&ts.length>1&&(time<ts[0]||time>=ts.at(-1)))time=ts[0];_toggle()}}
$('play').onclick=()=>togglePlay();
// --- collapsible panels remember their state ---
for(let d of document.querySelectorAll('details[data-key]')){let v=pref('panel:'+d.dataset.key);if(v!==null)d.open=v==='1';d.addEventListener('toggle',()=>pref('panel:'+d.dataset.key,d.open?'1':'0'))}
