// checkboxes give focus back so Space / shortcuts keep working
for(let cb of document.querySelectorAll('input[type=checkbox]'))cb.addEventListener('change',()=>cb.blur());

// ======================= v0.15: UI shell (tabs, floating toolbar, help) =======================
function showTab(name){if(!document.querySelector(`.tab[data-tab="${name}"]`))name='edit';for(let b of document.querySelectorAll('.tabs button'))b.classList.toggle('on',b.dataset.tab===name);for(let t of document.querySelectorAll('.tab'))t.classList.toggle('on',t.dataset.tab===name);pref('tab',name)}
for(let b of document.querySelectorAll('.tabs button'))b.addEventListener('click',()=>{showTab(b.dataset.tab);b.blur()});
showTab(pref('tab')||'edit');
// floating toolbar drives the (hidden) tool / axis / camera selects, and mirrors keyboard changes
for(let b of document.querySelectorAll('[data-tool]'))b.addEventListener('click',()=>{if(recording)return;setTool(b.dataset.tool);b.blur();syncToolbar();invalidate()});
for(let b of document.querySelectorAll('[data-axis]'))b.addEventListener('click',()=>{setAxis(b.dataset.axis);b.blur();syncToolbar()});
for(let b of document.querySelectorAll('[data-cam]'))b.addEventListener('click',()=>{$('cameraMode').value=b.dataset.cam;$('cameraMode').onchange();b.blur();syncToolbar();invalidate()});
function syncToolbar(){let t=$('tool').value,a=$('axis').value,c=$('cameraMode').value;
 for(let b of document.querySelectorAll('[data-tool]'))b.classList.toggle('on',b.dataset.tool===t);
 for(let b of document.querySelectorAll('[data-axis]'))b.classList.toggle('on',b.dataset.axis===a);
 for(let b of document.querySelectorAll('[data-cam]'))b.classList.toggle('on',b.dataset.cam===c);
 $('axisSeg').classList.toggle('dim',t==='camera'||t==='ik');$('camSeg').classList.toggle('dim',t!=='camera')}
{let _d=draw;draw=function(){_d();syncToolbar()}}
window.addEventListener('keyup',syncToolbar);syncToolbar();
// help dialog
$('helpBtn').onclick=()=>{$('helpDlg').showModal();$('helpBtn').blur()};$('helpClose').onclick=()=>$('helpDlg').close();
$('helpDlg').addEventListener('click',e=>{if(e.target===$('helpDlg'))$('helpDlg').close()});
