const TOOL_HINT={rotate:'Bấm khớp để chọn · kéo vòng màu để xoay · chỉnh số chính xác ở cột phải',move:'Bấm nhân vật / vật thể · kéo mũi tên màu để di chuyển theo trục',scale:'Bấm vật thể · kéo khối màu để đổi kích thước',ik:'Kéo cổ tay, cổ chân, khuỷu hoặc gối · chiều dài xương giữ nguyên, khớp tự gập'},CAM_HINT={orbit:'Kéo trái để xoay quanh điểm nhìn · kéo phải hoặc Shift + kéo để dịch · cuộn để zoom',pan:'Kéo để dịch camera ngang / dọc · cuộn để zoom',fly:'Kéo để đổi hướng nhìn · WASD đi, Q/E xuống/lên · cuộn để tiến/lùi'};
{let _s=syncToolbar;syncToolbar=function(){_s();let t=$('tool').value,h=t==='camera'?CAM_HINT[$('cameraMode').value]:TOOL_HINT[t];if(h&&$('navHint').textContent!==h)$('navHint').textContent=h}}
{let upd=()=>{let w=$('motionSel').value==='walk';$('motionHint').textContent=w?'Quãng đường âm = bước lùi, vẫn nhìn về phía trước.':'Chọn nhân vật trước. Chuyển động nối từ tư thế hiện tại, tự khoá chân và ghi chú.'};$('motionSel').addEventListener('change',upd);upd()}
syncToolbar();
