// ======================= v0.16: named props =======================
// Name / description of the selected prop (one undo step per edit, autosaved, exported in JSON + prompt)
let objEditSnap=false;const selObj=()=>selected?.kind==='object'?selected.index:null;
function syncObjCard(){let i=selObj(),card=$('objCard');card.hidden=i==null;$('handCard').hidden=i!=null;$('jointPick').hidden=i!=null;$('jointCardTitle').textContent=i!=null?'Vị trí · xoay · kích thước':'Khớp';if(i==null)return;let o=project.objects[i];if(document.activeElement!==$('objName'))$('objName').value=objectName(o,i);if(document.activeElement!==$('objDesc'))$('objDesc').value=o.desc||''}
